import java.io.*;

public class Main {
    static InputStream in = System.in;
    static byte[] buf = new byte[1 << 16];
    static int len = 0, pos = 0;

    static int readByte() throws IOException {
        if (pos == len) {
            len = in.read(buf, 0, buf.length);
            pos = 0;
            if (len <= 0) return -1;
        }
        return buf[pos++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != -1 && (c < '0' || c > '9') && c != '-') c = readByte();
        boolean neg = (c == '-');
        if (neg) c = readByte();
        long x = 0;
        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -x : x;
    }

    // True iff k*(2*A + k - 1) >= twoL, i.e. sum of the k smallest values in [A,B] (k*(2A+k-1)/2) >= L.
    // Overflow-safe: the product can reach ~8*10^20, which exceeds Long.MAX_VALUE.
    static boolean enough(long k, long A, long twoL) {
        long m = 2 * A + k - 1; // m <= A + B <= 4*10^10, m >= 2
        if (k > Long.MAX_VALUE / m) return true; // exact product overflows long -> certainly >= twoL (<= 2*10^13)
        return k * m >= twoL;
    }

    static long solve(long L, long A, long B) {
        long n = B - A + 1; // number of distinct available values
        long twoL = 2 * L;
        // If even using all values the total stays below L, João plays all n rounds.
        if (!enough(n, A, twoL)) return n;
        // Otherwise the game must cross L at some point; picking smallest values first
        // keeps partial sums pointwise minimal, delaying the crossing as much as possible.
        // Answer: minimal k in [1, n] with k*(2A+k-1)/2 >= L.
        long lo = 1, hi = n;
        while (lo < hi) {
            long mid = (lo + hi) >>> 1;
            if (enough(mid, A, twoL)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        int P = (int) nextLong();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < P; i++) {
            long L = nextLong(), A = nextLong(), B = nextLong();
            sb.append(solve(L, A, B)).append('\n');
        }
        System.out.print(sb);
    }
}
